import { motion, useSpring, useTransform } from 'framer-motion';
import { useEffect, useRef, useState } from 'react';
import { MOCK_HOME_CONTENT } from '@/data/homecontent';

function AnimatedNumber({
  value,
  color,
}: {
  value: string;
  color: 'teal' | 'gold';
}) {
  const [isInView, setIsInView] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  // extract numeric part and suffix
  const match = value.match(/^([\d.]+)(.*)$/);
  const numericValue = match ? parseFloat(match[1]) : 0;
  const suffix = match ? match[2] : value;

  const spring = useSpring(0, { stiffness: 60, damping: 20 });
  const display = useTransform(spring, (v) => {
    if (numericValue % 1 !== 0) {
      return v.toFixed(1);
    }
    return Math.round(v).toString();
  });

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !isInView) {
          setIsInView(true);
          spring.set(numericValue);
        }
      },
      { threshold: 0.5 }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [isInView, numericValue, spring]);

  const colorClass =
    color === 'teal'
      ? 'text-[#00E5C8]'
      : 'text-[#FFC83D]';

  const glowStyle =
    color === 'teal'
      ? { textShadow: '0 0 30px rgba(0, 229, 200, 0.5)' }
      : { textShadow: '0 0 30px rgba(255, 200, 61, 0.5)' };

  return (
    <div ref={ref} className={`text-4xl md:text-5xl font-bold ${colorClass}`} style={glowStyle}>
      <motion.span>{display}</motion.span>
      <span>{suffix}</span>
    </div>
  );
}

export default function StatsSection() {
  const { stats } = MOCK_HOME_CONTENT;

  return (
    <section id="stats" className="w-full py-20 md:py-24 relative">
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            'linear-gradient(180deg, transparent 0%, rgba(0,191,165,0.03) 50%, transparent 100%)',
        }}
      />

      <div className="max-w-7xl mx-auto px-4 md:px-6 relative">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-0 rounded-2xl border border-white/10 bg-white/[0.02] backdrop-blur-sm overflow-hidden">
          {stats.items.map((item, i) => (
            <motion.div
              key={item.label}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: '-10% 0px' }}
              transition={{ duration: 0.6, delay: i * 0.1 }}
              className={`relative p-8 md:p-10 text-center ${
                i < stats.items.length - 1
                  ? 'md:border-r border-white/10'
                  : ''
              } ${i % 2 === 0 && i < stats.items.length - 1 ? 'border-r border-white/10 md:border-r md:border-white/10' : ''} ${
                i < 2 ? 'border-b border-white/10 md:border-b-0' : ''
              }`}
            >
              <AnimatedNumber value={item.value} color={item.color} />
              <div className="mt-3 text-sm text-[#94A3B8]">{item.label}</div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
