import { useEffect, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { Anchor } from 'lucide-react';

interface TransitionOverlayProps {
  isOpen: boolean;
  onComplete: () => void;
  targetUrl: string;
}

const STEPS = [
  { text: '正在建立安全连接', duration: 1000 },
  { text: '加载知识库', duration: 1200 },
  { text: '启动监控面板', duration: 1000 },
];

export default function TransitionOverlay({
  isOpen,
  onComplete,
  targetUrl,
}: TransitionOverlayProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [fadeOut, setFadeOut] = useState(false);

  useEffect(() => {
    if (!isOpen) {
      setCurrentStep(0);
      setFadeOut(false);
      return;
    }

    let step = 0;
    const runStep = () => {
      if (step >= STEPS.length) {
        // open new tab
        window.open(targetUrl, '_blank');
        // fade out
        setFadeOut(true);
        setTimeout(() => {
          onComplete();
        }, 600);
        return;
      }
      setCurrentStep(step);
      setTimeout(() => {
        step++;
        runStep();
      }, STEPS[step].duration);
    };

    const timer = setTimeout(runStep, 400);
    return () => clearTimeout(timer);
  }, [isOpen, onComplete, targetUrl]);

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          key="transition-overlay"
          initial={{ opacity: 0 }}
          animate={{ opacity: fadeOut ? 0 : 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.6, ease: 'easeInOut' }}
          className="fixed inset-0 z-[100] flex items-center justify-center overflow-hidden"
        >
          {/* circular expand mask */}
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 30 }}
            transition={{ duration: 1.2, ease: [0.16, 1, 0.3, 1] }}
            className="absolute w-[100px] h-[100px] rounded-full bg-[#020B14]"
            style={{ transformOrigin: 'center' }}
          />

          {/* content */}
          <div className="relative z-10 flex flex-col items-center gap-10">
            {/* anchor with rotating ring */}
            <div className="relative w-28 h-28 flex items-center justify-center">
              <motion.div
                animate={{ rotate: 360 }}
                transition={{ duration: 3, repeat: Infinity, ease: 'linear' }}
                className="absolute inset-0 rounded-full border-2 border-transparent border-t-[#00BFA5] border-r-[#F0A500]/60"
                style={{
                  boxShadow: '0 0 20px rgba(0, 191, 165, 0.4)',
                }}
              />
              <motion.div
                animate={{ rotate: -360 }}
                transition={{ duration: 4, repeat: Infinity, ease: 'linear' }}
                className="absolute inset-2 rounded-full border border-[#00BFA5]/30 border-b-[#F0A500]"
              />
              <motion.div
                initial={{ scale: 0, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                transition={{ delay: 0.5, type: 'spring', stiffness: 200, damping: 15 }}
                className="relative"
              >
                <Anchor
                  size={44}
                  className="text-[#00BFA5]"
                  style={{
                    filter: 'drop-shadow(0 0 12px rgba(0, 191, 165, 0.9))',
                  }}
                />
              </motion.div>
            </div>

            {/* progress dots */}
            <div className="flex items-center gap-4">
              {STEPS.map((_, i) => (
                <div key={i} className="relative">
                  <motion.div
                    animate={
                      i <= currentStep
                        ? {
                            scale: [1, 1.3, 1],
                            backgroundColor: '#F0A500',
                            boxShadow: '0 0 16px rgba(240, 165, 0, 0.9)',
                          }
                        : {
                            scale: 1,
                            backgroundColor: 'rgba(255,255,255,0.2)',
                            boxShadow: 'none',
                          }
                    }
                    transition={{ duration: 0.4 }}
                    className="w-3 h-3 rounded-full bg-white/20"
                  />
                </div>
              ))}
            </div>

            {/* step text */}
            <motion.div
              key={currentStep}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.4 }}
              className="text-white/80 text-base tracking-wide"
            >
              {STEPS[currentStep]?.text}
            </motion.div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
