// EXPORTS: IChartDataPoint, IChartDataset, MOCK_CHART_DATASETS
export interface IChartDataPoint {
  timestamp: string
  value: number
}

export interface IChartDataset {
  id: string
  name: string
  unit: string
  color: string
  category: 'temperature' | 'pressure' | 'speed' | 'vibration'
  dataPoints: IChartDataPoint[]
}

function generateTimeSeries(baseValue: number, variance: number, count: number): IChartDataPoint[] {
  const points: IChartDataPoint[] = []
  const now = Date.now()
  for (let i = count - 1; i >= 0; i--) {
    const time = new Date(now - i * 3600000)
    const hours = time.getHours().toString().padStart(2, '0')
    const minutes = time.getMinutes().toString().padStart(2, '0')
    points.push({
      timestamp: `${hours}:${minutes}`,
      value: Number((baseValue + (Math.random() - 0.5) * variance).toFixed(2)),
    })
  }
  return points
}

