import { Anchor } from 'lucide-react';
import { MOCK_HOME_CONTENT } from '@/data/homecontent';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';

export default function Footer() {
  const { footer } = MOCK_HOME_CONTENT;

  return (
    <footer id="footer" className="w-full border-t border-[#00BFA5]/10 bg-[#020B14]/80 backdrop-blur-md">
      <div className="max-w-7xl mx-auto px-4 md:px-6 py-10">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="flex items-center gap-2">
            <Anchor size={20} className="text-[#00BFA5]" />
            <span className="text-white font-semibold">{footer.brand}</span>
          </div>

          <nav className="flex flex-wrap items-center justify-center gap-6 text-sm text-[#94A3B8]">
            {footer.links.map((link) => (
              <UniversalLink
                key={link.href}
                to={link.href}
                className="hover:text-[#00BFA5] transition-colors duration-300"
                onClick={(e) => {
                  if (link.href.startsWith('#')) {
                    e.preventDefault();
                    const el = document.getElementById(link.href.slice(1));
                    if (el) el.scrollIntoView({ behavior: 'smooth' });
                  }
                }}
              >
                {link.label}
              </UniversalLink>
            ))}
          </nav>

          <p className="text-xs text-[#64748B]">{footer.copyright}</p>
        </div>
      </div>
    </footer>
  );
}
