import { useEffect, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Anchor } from 'lucide-react';
import { cn } from '@/lib/utils';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';

const NAV_ITEMS = [
  { label: '关于', href: '#about', type: 'anchor' as const },
  { label: '功能', href: '#features', type: 'anchor' as const },
  { label: '数据', href: '/history', type: 'path' as const },
  { label: '架构', href: '#tech', type: 'anchor' as const },
  { label: '场景', href: '#scenarios', type: 'anchor' as const },
];

export default function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [hovered, setHovered] = useState<string | null>(null);
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 80);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const handleAnchorClick = (hash: string) => (e: React.MouseEvent) => {
    e.preventDefault();
    if (location.pathname !== '/') {
      navigate(`/${hash}`);
      return;
    }
    const el = document.getElementById(hash.slice(1));
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };

  return (
    <header
      className={cn(
        'fixed top-0 left-0 right-0 z-50 transition-all duration-500',
        scrolled
          ? 'bg-[#020B14]/70 backdrop-blur-xl border-b border-[#00BFA5]/20 shadow-[0_4px_30px_rgba(0_191_165_0.08)]'
          : 'bg-transparent border-b border-transparent'
      )}
    >
      <div className="max-w-7xl mx-auto px-4 md:px-6 h-16 flex items-center justify-between">
        <Link
          to="/"
          className="flex items-center gap-2 group"
          onClick={(e) => {
            if (location.pathname === '/') {
              e.preventDefault();
              window.scrollTo({ top: 0, behavior: 'smooth' });
            }
          }}
        >
          <div className="relative">
            <Anchor
              size={22}
              className="text-[#00BFA5] transition-all duration-300 group-hover:text-[#00E5C8] group-hover:drop-shadow-[0_0_8px_rgba(0_191_165_0.8)]"
            />
          </div>
          <span className="text-lg font-semibold text-white tracking-wide">
            轮机智脑
          </span>
        </Link>

        <nav className="hidden md:flex items-center gap-8">
          {NAV_ITEMS.map((item) =>
            item.type === 'anchor' ? (
              <UniversalLink
                key={item.href}
                to={item.href}
                onClick={handleAnchorClick(item.href)}
                onMouseEnter={() => setHovered(item.href)}
                onMouseLeave={() => setHovered(null)}
                className="relative text-sm text-[#94A3B8] hover:text-white transition-colors duration-300 py-1"
              >
                {item.label}
                <span
                  className={cn(
                    'absolute bottom-0 left-0 h-[2px] bg-gradient-to-r from-[#00BFA5] to-[#00E5C8] transition-all duration-300',
                    hovered === item.href ? 'w-full' : 'w-0'
                  )}
                  style={{
                    boxShadow:
                      hovered === item.href
                        ? '0 0 8px rgba(0, 191, 165, 0.8)'
                        : 'none',
                  }}
                />
              </UniversalLink>
            ) : (
              <Link
                key={item.href}
                to={item.href}
                onMouseEnter={() => setHovered(item.href)}
                onMouseLeave={() => setHovered(null)}
                className={cn(
                  'relative text-sm transition-colors duration-300 py-1',
                  location.pathname === item.href
                    ? 'text-white'
                    : 'text-[#94A3B8] hover:text-white'
                )}
              >
                {item.label}
                <span
                  className={cn(
                    'absolute bottom-0 left-0 h-[2px] bg-gradient-to-r from-[#00BFA5] to-[#00E5C8] transition-all duration-300',
                    (hovered === item.href || location.pathname === item.href)
                      ? 'w-full'
                      : 'w-0'
                  )}
                  style={{
                    boxShadow:
                      hovered === item.href || location.pathname === item.href
                        ? '0 0 8px rgba(0, 191, 165, 0.8)'
                        : 'none',
                  }}
                />
              </Link>
            )
          )}
        </nav>
      </div>
    </header>
  );
}
