import { useState } from 'react';
import { motion } from 'framer-motion';
import Header from '@/components/Header';
import Footer from '@/components/Footer';
import ParticleBackground from '@/components/ParticleBackground';
import HeroSection from './sections/HeroSection';
import AboutSection from './sections/AboutSection';
import FeaturesSection from './sections/FeaturesSection';
import StatsSection from './sections/StatsSection';
import TechSection from './sections/TechSection';
import ScenariosSection from './sections/ScenariosSection';
import CTASection from './sections/CTASection';
import ScrollDots from '@/components/ScrollDots';
import TransitionOverlay from '@/components/TransitionOverlay';

const DEMO_URL = 'http://127.0.0.1:7861';
const HISTORY_URL = 'http://127.0.0.1:7862';

export default function HomePage() {
  const [showTransition, setShowTransition] = useState(false);

  const handleStartDemo = () => {
    setShowTransition(true);
  };

  const handleTransitionComplete = () => {
    setShowTransition(false);
  };

  const handleViewHistory = () => {
    window.open(HISTORY_URL, '_blank');
  };

  return (
    <div className="relative min-h-screen bg-[#020B14] text-white overflow-x-hidden">
      <ParticleBackground />

      <div className="relative z-10">
        <Header />

        <main>
          <HeroSection
            onStartDemo={handleStartDemo}
            onViewHistory={handleViewHistory}
          />
          <AboutSection />
          <FeaturesSection />
          <StatsSection />
          <TechSection />
          <ScenariosSection />
          <CTASection onStartDemo={handleStartDemo} />
        </main>

        <Footer />
      </div>

      <ScrollDots />

      <TransitionOverlay
        isOpen={showTransition}
        onComplete={handleTransitionComplete}
        targetUrl={DEMO_URL}
      />
    </div>
  );
}
