import { useEffect, useState } from 'react';
import { cn } from '@/lib/utils';

const SECTIONS = [
  { id: 'hero', label: '首页' },
  { id: 'about', label: '关于' },
  { id: 'features', label: '功能' },
  { id: 'stats', label: '数据' },
  { id: 'tech', label: '架构' },
  { id: 'scenarios', label: '场景' },
];

export default function ScrollDots() {
  const [active, setActive] = useState('hero');

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActive(entry.target.id);
          }
        });
      },
      { threshold: 0.3, rootMargin: '-10% 0px -40% 0px' }
    );

    SECTIONS.forEach((s) => {
      const el = document.getElementById(s.id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, []);

  const handleClick = (id: string) => {
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };

  return (
    <div className="fixed right-6 top-1/2 -translate-y-1/2 z-40 hidden lg:flex flex-col gap-4">
      {SECTIONS.map((s) => (
        <button
          key={s.id}
          onClick={() => handleClick(s.id)}
          className="group relative flex items-center justify-center"
          aria-label={s.label}
        >
          <span
            className={cn(
              'block rounded-full transition-all duration-300',
              active === s.id
                ? 'w-3 h-3 bg-[#00BFA5] shadow-[0_0_12px_rgba(0_191_165_0.9)] scale-110'
                : 'w-2 h-2 bg-[#475569] group-hover:bg-[#00BFA5]/60'
            )}
          />
          <span className="absolute right-6 whitespace-nowrap text-xs text-white/80 bg-[#020B14]/90 backdrop-blur px-2 py-1 rounded border border-[#00BFA5]/30 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none">
            {s.label}
          </span>
        </button>
      ))}
    </div>
  );
}
